CREATE TABLE interview_policy_version(org_id TEXT NOT NULL,employee_id TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),cadence_unit TEXT NOT NULL CHECK(cadence_unit IN('day','week','month')),cadence_count INTEGER NOT NULL CHECK(cadence_count BETWEEN 1 AND 365),anchor_date TEXT NOT NULL CHECK(length(anchor_date)=10 AND date(anchor_date,'+0 days')=anchor_date),timezone TEXT NOT NULL CHECK(length(timezone) BETWEEN 1 AND 128 AND instr(timezone,char(0))=0),due_offset_days INTEGER NOT NULL CHECK(due_offset_days BETWEEN 0 AND 365),local_due_time TEXT NOT NULL CHECK(length(local_due_time)=5 AND local_due_time GLOB '[0-2][0-9]:[0-5][0-9]' AND substr(local_due_time,1,2)<'24'),window_through TEXT NOT NULL CHECK(length(window_through)=10 AND date(window_through,'+0 days')=window_through AND window_through>anchor_date),pause_json TEXT NOT NULL CHECK(json_valid(pause_json) AND json_type(pause_json)='array'),purpose TEXT NOT NULL CHECK(purpose='interview_followup'),ai_mode TEXT NOT NULL CHECK(ai_mode IN('disabled','manual_approved','periodic_structured_v1')),required_fields_json TEXT NOT NULL CHECK(json_valid(required_fields_json) AND json_type(required_fields_json)='array'),updated_by TEXT NOT NULL,updated_at INTEGER NOT NULL,PRIMARY KEY(org_id,employee_id,revision),FOREIGN KEY(org_id,employee_id) REFERENCES employee(org_id,id),FOREIGN KEY(org_id,updated_by) REFERENCES subject(org_id,id)) STRICT;
CREATE TABLE interview_policy(org_id TEXT NOT NULL,employee_id TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),cadence_unit TEXT NOT NULL CHECK(cadence_unit IN('day','week','month')),cadence_count INTEGER NOT NULL CHECK(cadence_count BETWEEN 1 AND 365),anchor_date TEXT NOT NULL CHECK(length(anchor_date)=10 AND date(anchor_date,'+0 days')=anchor_date),timezone TEXT NOT NULL CHECK(length(timezone) BETWEEN 1 AND 128 AND instr(timezone,char(0))=0),due_offset_days INTEGER NOT NULL CHECK(due_offset_days BETWEEN 0 AND 365),local_due_time TEXT NOT NULL CHECK(length(local_due_time)=5 AND local_due_time GLOB '[0-2][0-9]:[0-5][0-9]' AND substr(local_due_time,1,2)<'24'),window_through TEXT NOT NULL CHECK(length(window_through)=10 AND date(window_through,'+0 days')=window_through AND window_through>anchor_date),pause_json TEXT NOT NULL CHECK(json_valid(pause_json) AND json_type(pause_json)='array'),purpose TEXT NOT NULL CHECK(purpose='interview_followup'),ai_mode TEXT NOT NULL CHECK(ai_mode IN('disabled','manual_approved','periodic_structured_v1')),required_fields_json TEXT NOT NULL CHECK(json_valid(required_fields_json) AND json_type(required_fields_json)='array'),updated_by TEXT NOT NULL,updated_at INTEGER NOT NULL,PRIMARY KEY(org_id,employee_id),FOREIGN KEY(org_id,employee_id,revision) REFERENCES interview_policy_version(org_id,employee_id,revision),FOREIGN KEY(org_id,updated_by) REFERENCES subject(org_id,id)) STRICT;
CREATE TABLE followup_window(org_id TEXT NOT NULL,employee_id TEXT NOT NULL,id TEXT NOT NULL,policy_revision INTEGER NOT NULL CHECK(policy_revision>0),local_start TEXT NOT NULL CHECK(length(local_start)=10 AND date(local_start,'+0 days')=local_start),local_end TEXT NOT NULL CHECK(length(local_end)=10 AND date(local_end,'+0 days')=local_end AND local_end>local_start),start_at INTEGER NOT NULL,end_at INTEGER NOT NULL CHECK(end_at>start_at),due_at INTEGER NOT NULL,paused INTEGER NOT NULL CHECK(paused IN(0,1)),automation_state TEXT NOT NULL CHECK(automation_state IN('disabled','awaiting_manual_input','blocked','ready')),block_reason TEXT CHECK(block_reason IS NULL OR block_reason IN('automation_not_enabled','policy_expired','authorization_unavailable','provider_not_approved')),last_scanned_at INTEGER,PRIMARY KEY(org_id,id),UNIQUE(org_id,employee_id,policy_revision,local_start),FOREIGN KEY(org_id,employee_id,policy_revision) REFERENCES interview_policy_version(org_id,employee_id,revision)) STRICT;
CREATE TABLE assessment_command_receipt(org_id TEXT NOT NULL,subject_id TEXT NOT NULL,operation TEXT NOT NULL CHECK(operation='OP-AI-01'),key TEXT NOT NULL,digest BLOB NOT NULL CHECK(length(digest)=32),employee_id TEXT NOT NULL,result_revision INTEGER NOT NULL CHECK(result_revision>0),recorded_at INTEGER NOT NULL,PRIMARY KEY(org_id,subject_id,operation,key),FOREIGN KEY(org_id,subject_id) REFERENCES subject(org_id,id),FOREIGN KEY(org_id,employee_id,result_revision) REFERENCES interview_policy_version(org_id,employee_id,revision)) STRICT;
