CREATE TRIGGER authority_no_update BEFORE UPDATE ON delegation_authority BEGIN SELECT RAISE(ABORT,'immutable authority'); END;
CREATE TRIGGER authority_no_delete BEFORE DELETE ON delegation_authority BEGIN SELECT RAISE(ABORT,'immutable authority'); END;
CREATE TRIGGER access_grant_owner_immutable BEFORE UPDATE ON access_grant WHEN NEW.id IS NOT OLD.id OR NEW.org_id IS NOT OLD.org_id OR NEW.subject_id IS NOT OLD.subject_id OR NEW.capability IS NOT OLD.capability OR NEW.category IS NOT OLD.category OR NEW.scope_kind IS NOT OLD.scope_kind OR NEW.scope_id IS NOT OLD.scope_id OR NEW.employee_id IS NOT OLD.employee_id OR NEW.purpose IS NOT OLD.purpose OR NEW.object_ref IS NOT OLD.object_ref OR NEW.object_kind IS NOT OLD.object_kind OR NEW.object_employee_id IS NOT OLD.object_employee_id OR NEW.interview_id IS NOT OLD.interview_id OR NEW.note_head_id IS NOT OLD.note_head_id OR NEW.note_version_id IS NOT OLD.note_version_id OR NEW.action_item_id IS NOT OLD.action_item_id OR NEW.compensation_proposal_id IS NOT OLD.compensation_proposal_id OR NEW.compensation_event_id IS NOT OLD.compensation_event_id OR NEW.compensation_term_id IS NOT OLD.compensation_term_id BEGIN SELECT RAISE(ABORT,'immutable interview owner'); END;
CREATE TRIGGER access_grant_bonus_employee_scope BEFORE INSERT ON access_grant WHEN NEW.capability IN('bonus.target.manage','bonus.propose','bonus.approve','bonus.payment.record','compensation.extension.manage') AND NEW.object_kind IS NOT NULL BEGIN SELECT RAISE(ABORT,'bonus grants use employee scope'); END;
CREATE TABLE oidc_transaction_v9(state_hash BLOB PRIMARY KEY CHECK(length(state_hash)=32),binding_hash BLOB NOT NULL CHECK(length(binding_hash)=32),sealed_bytes BLOB NOT NULL CHECK(length(sealed_bytes)>=28),key_version INTEGER NOT NULL CHECK(key_version=1),created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL CHECK(expires_at>created_at AND expires_at<=created_at+600000000),mode TEXT NOT NULL CHECK(mode IN('login','step_up')),action TEXT NOT NULL CHECK(action IN('','pii.write','access_grant.manage','note.publish','sensitive.export','compensation.read','compensation.propose','compensation.approve','bonus.target.manage','bonus.propose','bonus.approve','bonus.payment.record','compensation.extension.manage','interview_policy.manage')),return_route TEXT NOT NULL CHECK(length(return_route)<=128),previous_hash BLOB,expected_org TEXT,expected_subject TEXT,expected_epoch INTEGER,expected_identity BLOB,consumed INTEGER NOT NULL DEFAULT 0 CHECK(consumed IN(0,1)),issued_hash BLOB REFERENCES session(token_hash),FOREIGN KEY(previous_hash,expected_org,expected_subject) REFERENCES session(token_hash,org_id,subject_id),FOREIGN KEY(expected_org,expected_subject) REFERENCES subject(org_id,id),FOREIGN KEY(expected_identity,expected_org,expected_subject) REFERENCES subject_identity(digest,org_id,subject_id),CHECK((previous_hash IS NULL AND expected_org IS NULL AND expected_subject IS NULL AND expected_epoch IS NULL) OR (previous_hash IS NOT NULL AND expected_org IS NOT NULL AND expected_subject IS NOT NULL AND expected_epoch IS NOT NULL AND expected_epoch>0)),CHECK((mode='login' AND action='' AND expected_identity IS NULL) OR (mode='step_up' AND action IN('pii.write','access_grant.manage','note.publish','sensitive.export','compensation.read','compensation.propose','compensation.approve','bonus.target.manage','bonus.propose','bonus.approve','bonus.payment.record','compensation.extension.manage','interview_policy.manage') AND previous_hash IS NOT NULL AND expected_identity IS NOT NULL)),CHECK(consumed=1 OR issued_hash IS NULL)) STRICT;
INSERT INTO oidc_transaction_v9 SELECT * FROM oidc_transaction;
DROP TABLE oidc_transaction;
ALTER TABLE oidc_transaction_v9 RENAME TO oidc_transaction;
CREATE INDEX oidc_transaction_expiry ON oidc_transaction(expires_at);
CREATE INDEX oidc_transaction_previous ON oidc_transaction(previous_hash);
