CREATE TRIGGER interview_policy_version_no_delete BEFORE DELETE ON interview_policy_version BEGIN SELECT RAISE(ABORT,'immutable assessment fact'); END;
CREATE TRIGGER followup_window_no_update BEFORE UPDATE ON followup_window WHEN NEW.org_id IS NOT OLD.org_id OR NEW.employee_id IS NOT OLD.employee_id OR NEW.id IS NOT OLD.id OR NEW.policy_revision IS NOT OLD.policy_revision OR NEW.local_start IS NOT OLD.local_start OR NEW.local_end IS NOT OLD.local_end OR NEW.start_at IS NOT OLD.start_at OR NEW.end_at IS NOT OLD.end_at OR NEW.due_at IS NOT OLD.due_at OR NEW.paused IS NOT OLD.paused BEGIN SELECT RAISE(ABORT,'immutable assessment owner'); END;
CREATE TRIGGER followup_window_no_delete BEFORE DELETE ON followup_window BEGIN SELECT RAISE(ABORT,'immutable assessment fact'); END;
